## **1. Python FastAPI Sidecar Engine (`sidecar.py`)**
```python
import os
import signal
import threading
import queue
from time import sleep
from typing import Optional

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import psutil  # For system monitoring (install: pip install psutil)

app = FastAPI()

# Thread-safe queue for background tasks
task_queue = queue.Queue()
is_running = threading.Event()
is_running.set()  # Start as running

class TaskResult(BaseModel):
    success: bool
    message: str

def worker():
    """Background worker that processes tasks from the queue."""
    while is_running.is_set():
        try:
            task, args, kwargs = task_queue.get(timeout=1)
            print(f"Executing task: {task.__name__} with args={args}, kwargs={kwargs}")
            result = TaskResult(success=True, message=f"Task {task.__name__} completed")
            # Simulate work
            sleep(0.5)
        except queue.Empty:
            continue

def shutdown_handler():
    """Graceful shutdown on SIGINT/SIGTERM."""
    print("Shutting down gracefully...")
    is_running.clear()  # Stop worker thread
    task_queue.join(timeout=2)  # Wait for pending tasks (max 2s)
    os._exit(0)

@app.on_event("startup")
def startup_event():
    """Start the background worker on app launch."""
    threading.Thread(target=worker, daemon=True).start()

@app.post("/api/task", response_model=TaskResult)
async def enqueue_task(task_name: str):
    """Example task endpoint (replace with your logic)."""
    if not hasattr(__import__("__main__"), task_name):
        raise HTTPException(status_code=400, detail="Invalid task")
    # Simulate adding a task to the queue
    return TaskResult(success=True, message=f"Task {task_name} queued")

@app.get("/api/health", response_model=dict)
async def health_check():
    """Report system state (RAM/VRAM usage)."""
    mem = psutil.virtual_memory()
    swap = psutil.swap_memory()
    return {
        "status": "healthy",
        "ram_usage_percent": mem.percent,
        "ram_total_gb": round(mem.total / (1024 ** 3), 2),
        "swap_usage_percent": swap.percent if swap else None,
    }

if __name__ == "__main__":
    import uvicorn
    signal.signal(signal.SIGINT, lambda *_: shutdown_handler())
    signal.signal(signal.SIGTERM, lambda *_: shutdown_handler())
    uvicorn.run(app, host="0.0.0.0", port=8000)
```

### **Key Features:**
- **Thread-safe task queue** with a background worker.
- **Health endpoint** (`/api/health`) reporting RAM/VRAM usage via `psutil`.
- **Graceful shutdown** on `SIGINT`/`SIGTERM`, waiting for pending tasks.
- **FastAPI** for lightweight HTTP handling.

