## **2. Rust (Tauri) Client (`main.rs`)**
```rust
use std::process::{Command, Child, Stdio};
use std::thread;
use std::time::{Duration, Instant};
use serde_json::Value;

fn spawn_sidecar() -> Option<Child> {
    let mut cmd = Command::new("python3");
    cmd.arg("sidecar.py")
       .stdout(Stdio::piped())
       .stderr(Stdio::piped());
    cmd.spawn().ok()
}

fn poll_health(child: &mut Child) -> bool {
    if child.try_wait().is_ok() { return false; } // Process died
    let output = Command::new("curl")
        .arg("-s")
        .arg("http://localhost:8000/api/health")
        .output()
        .ok()?;
    let status: Value = serde_json::from_slice(&output.stdout).unwrap();
    status["status"] == "healthy"
}

fn main() {
    let mut child = spawn_sidecar().expect("Failed to start sidecar");
    let mut backoff = 1.0; // Exponential backoff (seconds)

    loop {
        if poll_health(&mut child) {
            println!("Sidecar is healthy!");
            break;
        }
        thread::sleep(Duration::from_secs_f32(backoff));
        backoff = backoff.min(60.0).powf(2); // Cap at 1 minute
    }

    // Handle unexpected termination
    if let Err(e) = child.wait() {
        eprintln!("Sidecar crashed: {:?}", e);
    }
}
```

### **Key Features:**
- Spawns the Python process and monitors it.
- Polls `/api/health` with exponential backoff (1s → 2s → 4s → ...).
- Detects crashes via `try_wait()`.

