## **3. Node.js Client (`client.js`)**
```javascript
const { spawn } = require('child_process');
const axios = require('axios');

async function startSidecar() {
    const child = spawn('python3', ['sidecar.py'], {
        stdio: 'inherit',
    });

    let backoff = 1000; // Start with 1s
    while (true) {
        try {
            const response = await axios.get('http://localhost:8000/api/health');
            if (response.data.status === 'healthy') {
                console.log('Sidecar is healthy!');
                return child;
            }
        } catch (err) {
            console.error('Health check failed:', err.message);
        }

        // Exponential backoff
        await new Promise(resolve => setTimeout(resolve, backoff));
        backoff = Math.min(backoff * 2, 60_000); // Cap at 1 minute
    }
}

const sidecarProcess = startSidecar().catch(err => {
    console.error('Failed to start sidecar:', err);
});

process.on('SIGINT', () => {
    if (sidecarProcess) sidecarProcess.kill();
});
```

### **Key Features:**
- Spawns the Python process and monitors it.
- Uses exponential backoff for health checks.
- Handles `SIGINT` to clean up.

